func (this *Test_org_eclipse_swt_widgets_Text) Test_setTopIndexI() {
	if SwtTestUtilIsGTK || SwtTestUtilIsCocoa {
		if SwtTestUtilVerbose {
			fmt.Fprintln(os.Stdout, "Excluded test_setTopIndexI(org.eclipse.swt.tests.junit.Test_org_eclipse_swt_widgets_Text)")
		}
		return
	}
	var number int32 = 100
	for i := int32(0); i < number; i++ {
		this.text.Append("01234\n")
	}
	for i := int32(1); i < number; i++ {
		this.text.SetTopIndex(i)
		junit.AssertEquals(int32(i), int32(this.text.GetTopIndex()))
	}
	this.text.SetTopIndex(number + 5)
	junit.AssertEquals(int32(number), int32(this.text.GetTopIndex()))
	this.MakeCleanEnvironment(true)
	this.text.SetText("01234567890")
	this.text.Append(fmt.Sprintf("%s01234567890", swt.TextDELIMITER))
	this.text.SetTopIndex(0)
	junit.AssertEquals(int32(0), int32(this.text.GetTopIndex()))
	this.text.SetTopIndex(1)
	junit.AssertEquals(int32(0), int32(this.text.GetTopIndex()))
	this.text.SetTopIndex(17)
	junit.AssertEquals(int32(0), int32(this.text.GetTopIndex()))
	this.text.SetText("")
	for i := int32(0); i < number; i++ {
		this.text.Append(fmt.Sprintf("01234%s", swt.TextDELIMITER))
	}
	for i := int32(0); i < number; i++ {
		this.text.SetTopIndex(i)
		junit.AssertEquals(int32(0), int32(this.text.GetTopIndex()))
	}
}

